import logging
import time
from threading import Thread

from taf.ue.android.utils.ue_pc_logger import LoggerAdapter4EmptyExtra


class TakeCareThread(Thread):
    """Care taker thread for stuff like voice calls, data transfers, UEs ETC."""

    def __init__(self, carer, care_step_time, thread_namesufix=""):
        """

        :param carer:
        :param care_step_time:
        :param thread_namesufix:
        """
        self.carer = carer
        self.to_care = {}
        self.care_step_time = care_step_time
        self._keep_going = True
        raw_logger = logging.getLogger("ute_ue.uepc")
        self.logger = LoggerAdapter4EmptyExtra(raw_logger, {'area': 'UEPOOL'})
        self.thread_namesufix = str(thread_namesufix)
        super().__init__(name=f"TakeCareThread{self.thread_namesufix}")

    def add_careable(self, key, value):
        """
        Careable is an object on which take_care() method is performed
        :param key:
        :param value:
        :return:
        """
        self.logger.debug(f"add_careable, key = {key}, value = {value}")
        self.to_care[key] = value
        self.carer.take_care(key, value)
        if not self.is_alive():
            super().__init__(name=f"TakeCareThread{self.thread_namesufix}")
            self._keep_going = True
            self.start()

    def remove_careable(self, key):
        """
        :param key:
        :return:
        """
        self.logger.debug(f"remove_careable, key = {key}", exc_info=True)
        if self.to_care.pop(key, None) is None:
            self.logger.debug(f"{key} was already removed from items to care")

    def run(self):
        """Run"""
        try:
            self.logger.debug("TakeCareThread run start")
            self._run_taking_care()
            self.logger.debug("TakeCareThread run normaly finish")
        except Exception as e:  # pylint: disable=broad-except
            self.logger.debug("exception in _run_taking_care, it should never happend, " + str(e), exc_info=True)
            self.logger.exception(e)
        finally:
            self.logger.debug("TakeCareThread run finally finish")

    def _run_taking_care(self):
        while self._keep_going:
            for key, value in list(self.to_care.items()):
                if not self._keep_going:
                    return
                self._perform_take_care_with_error_handling(key, value)
            time.sleep(self.care_step_time)

    def _perform_take_care_with_error_handling(self, key, value):
        try:
            self.carer.take_care(key, value)
        except Exception as e:  # pylint: disable=broad-except
            try:
                self.carer.report_exception(key, value, e)
            except Exception:  # pylint: disable=broad-except
                pass  # report_exception should reported exception
                # do not write anything to log here to avoid to many logs like in:
                # https://jira3.int.net.nokia.com/browse/GVETEAWRO-4703
                # Jacek Skoczylas

    def clear_and_finish(self):
        """
        Terminates thread. Removes all careables from this object
        :return:
        """
        self.logger.debug("clear_and_finish, start", exc_info=True)
        self._keep_going = False
        self.logger.debug("clear_and_finish, end")


class IAbstractTakeCarer:
    """Abstract class for care takers"""

    def take_care(self, key, value):
        """
        Takes care of given object for example keep reservation for given UE
        :param key:
        :param value:
        :return:
        """
        pass

    def report_exception(self, key, value, exception):
        """
        Handles srror thrown by take_care method
        :param key:
        :param value:
        :param exception:
        :return:
        """
        pass
